import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"LINE Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/line.md","filePath":"integrations/channels/line.md","lastUpdated":1790952322000}'),s={name:"integrations/channels/line.md"};function i(r,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="line-channel-configuration" tabindex="-1">LINE Channel Configuration <a class="header-anchor" href="#line-channel-configuration" aria-label="Permalink to &quot;LINE Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to a LINE Official Account: users add the linked account as a friend and chat with the bot one-on-one.</p><div class="warning custom-block"><p class="custom-block-title">Limits</p><ul><li>Private chats only. Group and multi-person room messages are ignored — inviting the bot into a LINE group has no effect.</li><li>Output is plain text; Markdown is not rendered.</li><li>Outbound media is limited to PNG/JPEG images. Images must be publicly reachable over HTTPS and within LINE&#39;s size limits (10 MB original, 1 MB preview); non-image attachments cannot be sent.</li><li>Inbound audio, video, stickers, and location messages are not processed. Inbound images must be hosted by LINE itself (the normal case for photos sent from the app).</li><li>Responses arrive as complete messages — LINE does not support incremental streaming output — and long replies are split into multiple messages at LINE&#39;s 5000-character limit.</li><li>Replies are delivered through the LINE <strong>Push API</strong>, so they count against your LINE plan&#39;s push message quota.</li></ul></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>LINE delivers messages to Memoh through a <strong>webhook</strong>, and LINE&#39;s servers also fetch outbound images from your deployment, so Memoh must expose a public HTTPS endpoint:</p><ul><li>Set <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> to your public HTTPS origin (no path, port, or private address), or</li><li>Enable the Cloudflare Quick Tunnel profile in the server deploy stack, and Memoh will obtain a public URL automatically.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-create-a-line-messaging-api-channel" tabindex="-1">1. Create a LINE Messaging API channel <a class="header-anchor" href="#_1-create-a-line-messaging-api-channel" aria-label="Permalink to &quot;1. Create a LINE Messaging API channel&quot;">​</a></h3><p>In the LINE Developers Console:</p><ol><li>Go to the <a href="https://developers.line.biz/console/" target="_blank" rel="noreferrer">LINE Developers Console</a>.</li><li>Create a provider (or pick an existing one), then create a <strong>Messaging API</strong> channel. This links the channel to a LINE Official Account.</li><li>In <strong>Basic settings</strong>, copy the <strong>Channel secret</strong>.</li><li>In the <strong>Messaging API</strong> tab, issue and copy a <strong>Channel access token</strong> (long-lived).</li></ol><blockquote><p>Official Guide: <a href="https://developers.line.biz/en/docs/messaging-api/getting-started/" target="_blank" rel="noreferrer">LINE Messaging API - Getting Started</a></p></blockquote><h3 id="_2-add-the-channel-in-memoh" tabindex="-1">2. Add the channel in Memoh <a class="header-anchor" href="#_2-add-the-channel-in-memoh" aria-label="Permalink to &quot;2. Add the channel in Memoh&quot;">​</a></h3><p>In Memoh:</p><ol><li>Open the bot&#39;s <strong>Platforms</strong> tab.</li><li>Click <strong>Add Channel</strong> and select <strong>LINE</strong>.</li><li>Paste your <strong>Channel Secret</strong> and <strong>Channel Access Token</strong>.</li><li>Click <strong>Save</strong> (or <strong>Save and Enable</strong>). The webhook callback URL is generated only after the configuration is saved.</li></ol><h3 id="_3-register-the-webhook" tabindex="-1">3. Register the webhook <a class="header-anchor" href="#_3-register-the-webhook" aria-label="Permalink to &quot;3. Register the webhook&quot;">​</a></h3><p>In Memoh, after saving, the panel shows a read-only <strong>WebHook Callback URL</strong> in the form:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;your-public-base&gt;/channels/line/webhook/&lt;config_id&gt;</span></span></code></pre></div><p>Register it in one of two ways:</p><ul><li>Click <strong>Set in LINE</strong> — Memoh writes the webhook endpoint into your LINE channel directly through the Messaging API. Save any pending changes first, otherwise the button reports an error.</li><li>Or click <strong>Copy</strong> and paste the URL into <strong>Messaging API → Webhook URL</strong> in the LINE Developers Console manually.</li></ul><p>Then, in the LINE Developers Console, make sure <strong>Use webhook</strong> is enabled for the channel.</p><p>Memoh verifies incoming webhooks against your <strong>Channel Secret</strong> and deduplicates events for 24 hours.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Channel Secret</strong></td><td>Yes</td><td>Copied from <strong>Basic settings</strong> of the Messaging API channel.</td></tr><tr><td><strong>Channel Access Token</strong></td><td>Yes</td><td>Long-lived token issued in the <strong>Messaging API</strong> tab.</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Add the linked LINE Official Account as a friend, then send <code>/help</code> to the bot in the one-on-one chat. The bot replies with its command list, which confirms the channel is working.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>Disable or remove the channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To rotate credentials, update <strong>Channel Secret</strong> / <strong>Channel Access Token</strong> in the same panel and save.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h2><h3 id="no-public-base-url" tabindex="-1">The panel warns that no public base URL is available <a class="header-anchor" href="#no-public-base-url" aria-label="Permalink to &quot;The panel warns that no public base URL is available {#no-public-base-url}&quot;">​</a></h3><p>The webhook callback URL cannot be built without a public HTTPS origin. Fix the <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> / Cloudflare Quick Tunnel setup described in the prerequisites first.</p>',30)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
